from __future__ import unicode_literals

import unittest
from functools import partial
from lxml import etree

from ute_common_config_files.scfc.exceptions import ScfcFixerException
from ute_common_config_files.scfc.scfc import Scfc

from ute_common_util.test.temp import xml_from_resource, path_to_temp_copy_of_resource, path_to_resource

path_to_resource = partial(path_to_resource, __name__)
xml_from_resource = partial(xml_from_resource, __name__)
path_to_temp_copy_of_resource = partial(path_to_temp_copy_of_resource, __name__)


class TestScfcWithCommonSCFC(unittest.TestCase):

    @path_to_resource('resources/scfc/test_SCFC.xml')
    def setUp(self, scfc_path):
        self.scfc_path = scfc_path
        self.scfc = Scfc(scfc_path)

    def test_set_bts_name(self):
        self.scfc.set_bts_name('TL123')
        self.assertEqual(self.scfc.find_single_managed_object('BTSSCL').find_param('btsName').value, 'TL123')

    def test_set_bts_id(self):
        self.scfc.set_bts_id(2)
        scfc_content = etree.tostring(self.scfc.xml, encoding="unicode")
        self.assertFalse('MRBTS-1' in scfc_content)
        self.assertFalse('LNBTS-1' in scfc_content)

    def test_get_managed_object_class(self):
        self.assertEqual(self.scfc._get_managed_object_class('/MRBTS-123'), 'MRBTS')
        self.assertEqual(self.scfc._get_managed_object_class('/MRBTS-1/BTSSCL-1/LCELL-1'), 'LCELL')
        self.assertEqual(self.scfc._get_managed_object_class('/ABC123-456'), 'ABC123')

    def test_set_logical_cell_ids(self):
        self.scfc.set_logical_cell_ids([81, 82, 83])
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-1').find_param('lcrId').value, '81')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-2').find_param('lcrId').value, '82')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-3').find_param('lcrId').value, '83')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-1').find_param('phyCellId').value, '1')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-2').find_param('phyCellId').value, '2')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-3').find_param('phyCellId').value, '3')

    def test_set_logical_cell_ids_raise_length_exception(self):
        with self.assertRaises(ScfcFixerException):
            self.scfc.set_logical_cell_ids([81])

    def test_set_physical_cell_ids(self):
        self.scfc.set_physical_cell_ids([91, 92, 93])
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-1').find_param('phyCellId').value, '91')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-2').find_param('phyCellId').value, '92')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-3').find_param('phyCellId').value, '93')
        self.assertTrue(self.scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-1'))
        self.assertTrue(self.scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-2'))
        self.assertTrue(self.scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-3'))
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-1').find_param('lcrId').value, '1')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-2').find_param('lcrId').value, '2')
        self.assertEqual(self.scfc.find_managed_object('MRBTS-1/LNBTS-1/LNCEL-3').find_param('lcrId').value, '3')

    def test_set_physical_cell_ids_raise_length_exception(self):
        with self.assertRaises(ScfcFixerException):
            self.scfc.set_physical_cell_ids([91])

    def test_set_oam_ip(self):
        self.scfc.set_oam_ip('10.0.6.66')
        self.assertEqual(self.scfc.find_single_managed_object('MPLANENW').find_param('oamPeerIpAddress').value, '10.0.6.66')


