class TestRemoveAllManagedObejctsExceptFirst(unittest.TestCase):
    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual([lcell.dist_name for lcell in scfc.find_managed_objects('LCELL')], ["MRBTS-1/BTSSCL-1/LCELL-2",
                                                                                             "MRBTS-1/BTSSCL-1/LCELL-3",
                                                                                             "MRBTS-1/BTSSCL-1/LCELL-1"])

        scfc.remove_all_managed_obejcts_except_first('LCELL')
        self.assertEqual([lcell.dist_name for lcell in scfc.find_managed_objects('LCELL')], ["MRBTS-1/BTSSCL-1/LCELL-1"])


class TestShouldFindAllManagedObjectsWhichSuffixesMatchGivenManagedObjectClass(unittest.TestCase):
    @path_to_resource('resources/scfc/managed_objects_with_the_same_class_suffix.xml')
    def test(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual([lcell.dist_name for lcell in scfc.find_managed_objects('LCELL')], ["MRBTS-1/BTSSCL-1/ILCELL-1",
                                                                                             "MRBTS-1/BTSSCL-1/LCELL-2",
                                                                                             "MRBTS-1/BTSSCL-1/LCELL-3",
                                                                                             "MRBTS-1/BTSSCL-1/LCELL-1"])


class TestAdjustManagedObjectsCount(unittest.TestCase):
    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def setUp(self, scfc_path):
        self.scfc_path = scfc_path
        self.scfc = Scfc(scfc_path)

    def test_raise_exception(self):
        with self.assertRaises(ValueError):
            self.scfc.adjust_managed_objects_count("LCELL", 3, [4, 5])

    def test_remove_all_mos(self):
        self.scfc.adjust_managed_objects_count("LCELL", 0)
        self.assertEqual(self.scfc.find_managed_objects('LCELL'), [])

    def test_adjust_with_default_ids(self):
        self.scfc.adjust_managed_objects_count("LCELL", 5)
        self.assertEqual([mo.id for mo in self.scfc.find_managed_objects('LCELL')], [1, 2, 3, 4, 5])

    def test_adjust_with_ids_from_args(self):
        self.scfc.adjust_managed_objects_count("LCELL", 5, [1, 3, 5, 7, 9])
        self.assertEqual([mo.id for mo in self.scfc.find_managed_objects('LCELL')], [1, 3, 5, 7, 9])
